-- 23/10/2026 — Qualidade ONLINE (Kátia pelo celular). Tabelas qualidade_* FECHADAS:
-- RLS ligado + nenhum grant pra anon/authenticated. Só a Edge Function "qualidade" (chave secreta)
-- e o ws-agent do Lucas leem/gravam. Pessoas: só nome, casa e cargo.
create table if not exists qualidade_config (chave text primary key, valor text);
create table if not exists qualidade_sessoes (token_hash text primary key, criado_em timestamptz default now(), expira_em timestamptz not null);
create table if not exists qualidade_tentativas (ip text primary key, n int default 0, bloqueado_ate timestamptz, atualizado_em timestamptz default now());
create table if not exists qualidade_casas (id text primary key, nome text, apelido text, tipo text default 'loja', ordem int, responsavel text, email text, ativo int default 1, atualizado_em bigint);
create table if not exists qualidade_pessoas (id int primary key, nome text not null, casa text, cargo text);
create table if not exists qualidade_modelos (id bigint generated by default as identity primary key, nome text, tipo text, para text default 'todas', descricao text, ativo int default 1, criado_em bigint);
create table if not exists qualidade_perguntas (id bigint generated by default as identity primary key, modelo_id bigint, area text, ordem int, pergunta text, peso real default 1, ativo int default 1);
create table if not exists qualidade_relatorios (codigo text primary key, casa_id text, modelo_id bigint, modelo_nome text, data text, nutri text, acompanhou text, obs text,
  status text default 'rascunho', nota real, pontos real, peso_total real, n_verde int, n_amarela int, n_vermelha int, n_na int, n_sem int,
  demo int default 0, criado_em bigint, finalizado_em bigint, atualizado_em bigint);
create table if not exists qualidade_respostas (id bigint generated by default as identity primary key, codigo text references qualidade_relatorios(codigo) on delete cascade,
  pergunta_id bigint, area text, ordem int, pergunta text, peso real, resposta text, comentario text, fotos jsonb default '[]'::jsonb);
create index if not exists ix_qualidade_resp on qualidade_respostas (codigo);
create table if not exists qualidade_epi_catalogo (id bigint generated by default as identity primary key, nome text unique, tipo text, ca text, troca_dias int, ativo int default 1);
create table if not exists qualidade_epi_entregas (id bigint generated by default as identity primary key, pessoa_id int, pessoa_nome text, casa_id text, item_id bigint, item_nome text, tipo text,
  tamanho text, qtd int default 1, data_entrega text, ca text, ca_validade text, troca_em text, assinatura text, foto text, entregue_por text, obs text,
  status text default 'ativo', demo int default 0, criado_em bigint, atualizado_em bigint);
-- histórico do app de terceiro (lido do grupo pela Secretaria) — só pra o comparativo
create table if not exists qualidade_historico (codigo text primary key, casa_id text, data text, nota real, fonte text, ts bigint);
create table if not exists qualidade_historico_itens (id bigint generated by default as identity primary key, codigo text, area text, pergunta text, nota int, comentario text);
create index if not exists ix_qualidade_hist_itens on qualidade_historico_itens (codigo);

do $$ declare t text; begin
  foreach t in array array['qualidade_config','qualidade_sessoes','qualidade_tentativas','qualidade_casas','qualidade_pessoas','qualidade_modelos','qualidade_perguntas',
    'qualidade_relatorios','qualidade_respostas','qualidade_epi_catalogo','qualidade_epi_entregas','qualidade_historico','qualidade_historico_itens'] loop
    execute format('alter table %I enable row level security', t);
    execute format('revoke all on table %I from anon, authenticated', t);
  end loop;
end $$;

-- bucket PRIVADO das fotos (respostas, assinaturas e recibos de EPI) — só URL assinada
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('qualidade-privado', 'qualidade-privado', false, 5242880, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public = false;
